insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D3-S1-001', 'source'::public.t3a_content_family, 'Three things due Thursday', 'D3', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D3-S1-001", "title": "Three things due Thursday", "stage": 1, "stage_code": "S1", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d3_situation_class": "SC-D3-1", "interaction_pattern_family_id": "IPF-D3-01 (derived)", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "name_clearance_claim": "CLEARED — controlled role and entity labels only", "compatibility_class": "DEMO-ONLY", "source_sheet": {"scenario_class": "observation_ready", "dimensions_in_play": "D3, sampled through the workplace demand of ordering more work than the available time holds", "relevant_conduct": "the order stated; what was reduced, deferred or dropped; what was stated as held; what checks were named; what was done about the tool outage; the answer at R7", "irrelevant_conduct": "the merits of the order chosen; the content of the rate table; opinions about the tool", "stated_standard": "\"no pack goes to the client organization without the figures check and the cross-reference check.\" Exact participant-facing text at R1", "permitted_administration_variance": "Reveal order fixed. Screen-reader and extended-time accommodations permitted and recorded", "unsupported_inferences": "That any particular order is correct; that dropping a piece was a failure; anything about how the participant manages time as a trait", "cross_context_map": "Not established", "min_seconds": "420 / `max_seconds` — 1800", "compatibility_class": "DEMO-ONLY", "work_items": "(a) `WI-01` update the rate table — about three hours; (b) `WI-02` rebuild the summary deck — about six hours; (c) `WI-03` reconcile the exceptions log — about four hours", "deliverable_components": "(a) `DC-01` the rate table; (b) `DC-02` the summary deck; (c) `DC-03` the exceptions log", "stated_requirements": "(a) `SR-01` the figures check is run before the pack goes; (b) `SR-02` the cross-reference check is run before the pack goes; (c) `SR-03` the pack reaches the client organization by Thursday at noon", "available_checks": "(a) `CK-01` the figures check — about forty minutes; performable_in_session false at Stage 1, q_d3_04b_eligible in stated form only; (b) `CK-02` the cross-reference check — about forty minutes; performable_in_session false at Stage 1, q_d3_04b_eligible in stated form only", "available_means": "(a) `MN-01` ask the coordinator for the rate schedule outside the tool; performable_in_session false at Stage 1, q_d3_05b_eligible in stated form only; (b) `MN-02` use last month''s rate table and mark it as carried forward; performable_in_session false at Stage 1, q_d3_05b_eligible in stated form only", "time_available": "\"about ten working hours in total.\" Exact text at R1", "work_required": "three hours plus six hours plus four hours, and two checks of about forty minutes each. Exact text at R1", "blocking_dependency": "the scheduling tool is down until Wednesday afternoon and holds the only copy of the new rate schedule", "dependency_holder_role": "the coordinator. RETAINED FOR SOURCE TRUTH AND NEVER RENDERED", "moved_standard_point": "explicit none. Q-D3-08 is NOT SERVED because the source moves no requirement", "handover_point": "Thursday at noon. IT FALLS OUTSIDE THE OBSERVATION, so Q-D3-07 A4 is the reachable answer", "delivery_state_record": "at R7: the exceptions log is not started; the summary deck is not started; the rate table cannot be started until the tool returns", "delivery_test_point": "R7", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "mentor_action_sequence": "not_applicable. Stage 1 runs no beats", "d3_situation_class": "SC-D3-1"}, "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three items, ten hours, thirteen hours of work. R2 creates the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "On Q-D3-01 A1 or A2. `work_items` holds three"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what gives"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "On Q-D3-02 A1, A2 or A3"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "R3 asks what does not give; `stated_requirements` holds three"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "On Q-D3-03 A1"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R6 asks what is checked. A1 refuses at Stage 1 under Section 5.14"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "On Q-D3-04 A1 or A2. Only A2 is reachable as a parent at this Stage"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "R5 creates the opportunity. A1 UNREACHABLE at Stage 1"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "On Q-D3-05 A1 or A2. SERVED at this Stage in identifying form; only A2 is reachable as a parent"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "`blocking_dependency` is established at R4 and R5 asks about it"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "`blocking_dependency` is established at R4 and R5 asks about it"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "`handover_point` falls outside the observation, so A4 is the reachable answer"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "On Q-D3-07 A1 or A2, therefore NOT REACHED"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "`moved_standard_point` is none. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "`delivery_test_point` at R7"}], "script": null, "reveals": [{"id": "R1", "text": "The situation text above. (Establishes `work_items`, `time_available`, `work_required`, `stated_requirements`.)"}, {"id": "R2", "text": "QUESTION: What do you do first, and in what order do you take the three pieces?"}, {"id": "R3", "text": "QUESTION: Ten hours does not cover thirteen hours of work plus the checks. What gives, and what does not?"}, {"id": "R4", "text": "A message from the coordinator: \"The scheduling tool is down until Wednesday afternoon. The new rate schedule is only in there.\" (Establishes `blocking_dependency`.)"}, {"id": "R5", "text": "QUESTION: What, if anything, do you do about the rate table now?"}, {"id": "R6", "text": "QUESTION: Before the pack goes on Thursday, what do you check, and how?"}, {"id": "R7", "text": "DELIVERY-STATE TEST. The coordinator writes: \"Just so I have it right — as of now, which of the three is furthest along and which has not been started?\" QUESTION: What is your answer?"}], "text_blocks": {"The situation as the participant meets it": "You work in the delivery team. It is Tuesday morning. Three pieces of work are due to the client organization on Thursday at noon.\nThe rate table needs updating from the new schedule. It takes about three hours.\nThe summary deck needs rebuilding against the current figures. It takes about six hours.\nThe exceptions log needs reconciling. It takes about four hours.\nYou have Tuesday and Wednesday. That is about ten working hours in total.\nThe team standard, written in the delivery handbook, is that no pack goes to the client organization without the figures check and the cross-reference check. Each check takes about forty minutes."}, "narrative": {"The situation as the participant meets it": "> You work in the delivery team. It is Tuesday morning. Three pieces of work are due to the client organization on Thursday at noon.\n>\n> The rate table needs updating from the new schedule. It takes about three hours.\n> The summary deck needs rebuilding against the current figures. It takes about six hours.\n> The exceptions log needs reconciling. It takes about four hours.\n>\n> You have Tuesday and Wednesday. That is about ten working hours in total.\n>\n> The team standard, written in the delivery handbook, is that no pack goes to the client organization without the figures check and the cross-reference check. Each check takes about forty minutes.", "Reveal sequence": "- R1 — The situation text above. (Establishes `work_items`, `time_available`, `work_required`, `stated_requirements`.)\n- R2 — QUESTION: What do you do first, and in what order do you take the three pieces?\n- R3 — QUESTION: Ten hours does not cover thirteen hours of work plus the checks. What gives, and what does not?\n- R4 — A message from the coordinator: \"The scheduling tool is down until Wednesday afternoon. The new rate schedule is only in there.\" (Establishes `blocking_dependency`.)\n- R5 — QUESTION: What, if anything, do you do about the rate table now?\n- R6 — QUESTION: Before the pack goes on Thursday, what do you check, and how?\n- R7 — DELIVERY-STATE TEST. The coordinator writes: \"Just so I have it right — as of now, which of the three is furthest along and which has not been started?\" QUESTION: What is your answer?\n\nR7 is the `delivery_test_point`. It is factual, asks about state, and signals no doubt.", "What this fixture proves": "Three questions are served and cannot reach their first answer, for two different reasons: a written Stage 1 response cannot evidence a performed act, and the handover falls outside the window. Q-D3-08 is NOT SERVED because the source presents no moved standard, so it writes no row at all. A build that treats an unreachable answer as a missing value has failed."}, "source_version_hash": "f54ef00eaaa0da14c25670b6db19dd133ca8da53b6ce3069e3982325954379c7"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D3-S1-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D3-S1-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D3-S1-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D3-S1-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D3-S2-001', 'source'::public.t3a_content_family, 'The export that will not run', 'D3', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D3-S2-001", "title": "The export that will not run", "stage": 2, "stage_code": "S2", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d3_situation_class": "SC-D3-2", "interaction_pattern_family_id": "IPF-D3-02 (derived)", "administration_form_id": "AF-S2-SEVEN-BEAT", "name_clearance_claim": "CLEARED", "compatibility_class": "DEMO-ONLY", "source_sheet": {"dimensions_in_play": "D3, sampled through the workplace demand of delivering a fixed pack when the system that produces half of it is unavailable", "relevant_conduct": "the order stated; which sections were reduced, deferred or dropped; which requirement was stated as held; which checks were run or stated; which means were used; what was done about the export; whether the pack was described as going out with its gaps identified; the answer at B6", "irrelevant_conduct": "the technical cause of the export failure; the vendor''s responsiveness; whether the participant seems calm", "stated_standard": "\"every figure in the pack carries its source reference and the pack is reconciled against the ledger before issue.\" Exact pre-brief text", "permitted_administration_variance": "Pronunciation only. Accommodations changing channel or pause window are recorded and set `timing_not_comparable`", "unsupported_inferences": "That dropping a section would be wrong or right; that chasing the vendor was required; anything about resourcefulness", "cross_context_map": "Not established", "min_seconds": "480 / `max_seconds` — 900", "compatibility_class": "DEMO-ONLY", "work_items": "(a) `WI-01` the volumes section — depends on the export; (b) `WI-02` the exceptions section — does not depend on the export; (c) `WI-03` the service-level section — depends on the export; (d) `WI-04` the commentary — does not depend on the export", "deliverable_components": "(a) `DC-01` volumes; (b) `DC-02` exceptions; (c) `DC-03` service levels; (d) `DC-04` commentary", "stated_requirements": "(a) `SR-01` every figure carries its source reference; (b) `SR-02` the pack is reconciled against the ledger before issue; (c) `SR-03` the pack is issued by the end of today", "available_checks": "(a) `CK-01` source-reference check across every figure; performable_in_session true, observable_act true, q_d3_04b_eligible true; (b) `CK-02` ledger reconciliation; performable_in_session true, observable_act true, q_d3_04b_eligible true", "available_means": "(a) `MN-01` take last month''s volumes and mark them as carried forward; performable_in_session true, observable_act true, q_d3_05b_eligible true; (b) `MN-02` request a manual extract from the vendor on the open ticket; performable_in_session false, this is a stated intention and NOT an act; q_d3_05b_eligible false; (c) `MN-03` issue the pack with the two dependent sections marked as pending; performable_in_session true, observable_act true, q_d3_05b_eligible true", "time_available": "until the end of today. Exact pre-brief text", "work_required": "four sections, two of which depend on an unavailable export, plus two checks", "blocking_dependency": "the reporting export has failed with no restoration time", "dependency_holder_role": "the vendor support desk. RETAINED AND NEVER RENDERED", "moved_standard_point": "explicit none. Q-D3-08 is NOT SERVED because the source moves no requirement", "handover_point": "the end of today, at issue of the pack. IT FALLS WITHIN THE OBSERVATION as a stated intention at B4, so Q-D3-07 A1, A2 and A3 are all reachable", "delivery_state_record": "at B6: exceptions complete; commentary complete; volumes not produced; service levels not produced", "delivery_test_point": "B6", "mentor_action_sequence": "B1 SAY, is_decision_point false; B2 PAUSE, is_decision_point TRUE; B3 ASK, serves the enquiry question; B4 ASK, serves Q-D3-02 and Q-D3-07; B5 ASK, serves Q-D3-05 and Q-D3-06a; B6 ASK, serves Q-D3-09; B7 SAY, is_decision_point false", "d3_situation_class": "SC-D3-2"}, "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items, two blocked; B2 and B3 create the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "On Q-D3-01 A1 or A2"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what goes out"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "On Q-D3-02 A1, A2 or A3"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements, at least one of which cannot hold with the other"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "On Q-D3-03 A1"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "Two checks performable in session. A1 REACHABLE"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "On Q-D3-04 A1 or A2"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, two performable in session"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "On Q-D3-05 A1. MN-02 is NOT eligible — stating that a manual extract will be requested is an intention"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "B5 asks about the export directly"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "B5 asks about the export directly"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The handover is inside the observation. ALL FOUR ANSWERS REACHABLE"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "On Q-D3-07 A1 or A2. Draws on the SAME family as Q-D3-02b and is captured independently"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "`moved_standard_point` is none. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "`delivery_test_point` at B6"}], "script": [{"beat": "B1", "type": "SAY", "verbatim_text": "\"Thanks for the time. This is the regular check-in on the operations pack. I will let you start.\"", "capture": "None. B1 IS NEVER A QUESTION"}, {"beat": "B2", "type": "PAUSE", "verbatim_text": "Silence, ten to fifteen seconds. No prompt, no fill, no shortening", "capture": "C1, C1b, C2, C7 if the participant sets out a position here"}, {"beat": "B3", "type": "ASK 1", "verbatim_text": "\"Where has the pack got to?\"", "capture": "C1, C1b, C2, C2b, C3, C3b"}, {"beat": "B4", "type": "ASK 2", "verbatim_text": "\"If the export does not come back today, what goes out at five?\"", "capture": "C2, C2b, C3, C3b, C7, C7b"}, {"beat": "B5", "type": "ASK 3", "verbatim_text": "\"What are you doing about the export itself?\"", "capture": "C5, C5b, C6, C4, C4b"}, {"beat": "B6", "type": "ASK 4", "verbatim_text": "\"Just so I have it right — as of now, which sections are complete and which are not?\"", "capture": "C9"}, {"beat": "B7", "type": "SAY", "verbatim_text": "\"That is everything from me. Thanks.\"", "capture": "None"}], "reveals": [], "text_blocks": {"Participant pre-brief": "You prepare the monthly operations pack for the client organization. It has four sections: volumes, exceptions, service levels and commentary.\nThe pack is due at the end of today. The reporting export that produces the volumes and service-level figures has failed every time you have run it since yesterday afternoon. The vendor''s support desk has an open ticket and no restoration time.\nThe exceptions section and the commentary can be produced without the export.\nThe standing requirement, written in the pack template, is that every figure in the pack carries its source reference and that the pack is reconciled against the ledger before issue.\nYou have a scheduled check-in with your supervisor now."}, "narrative": {"Participant pre-brief": "— in writing before the session, not repeated in it.\n\n> You prepare the monthly operations pack for the client organization. It has four sections: volumes, exceptions, service levels and commentary.\n>\n> The pack is due at the end of today. The reporting export that produces the volumes and service-level figures has failed every time you have run it since yesterday afternoon. The vendor''s support desk has an open ticket and no restoration time.\n>\n> The exceptions section and the commentary can be produced without the export.\n>\n> The standing requirement, written in the pack template, is that every figure in the pack carries its source reference and that the pack is reconciled against the ledger before issue.\n>\n> You have a scheduled check-in with your supervisor now.", "Mentor brief": "The mentor reads the scripted lines of the supervisor. The supervisor knows the export has failed and does not know which sections are affected. The mentor must not suggest an order, must not propose dropping a section, and must not react expressively. No escalation, no repetition, no unscripted follow-up whatever the participant says.", "The four questions": "1. B3 — \"Where has the pack got to?\"\n2. B4 — \"If the export does not come back today, what goes out at five?\"\n3. B5 — \"What are you doing about the export itself?\"\n4. B6 — \"Just so I have it right — as of now, which sections are complete and which are not?\"", "What this fixture proves": "`deliverable_components` feeds two controls in one session. A participant who drops volumes and service levels and says so at issue selects DC-01 and DC-03 at Q-D3-02b AND at Q-D3-07b. THOSE ARE TWO FACTS, NOT A DUPLICATE — one records that the components were cut, the other that the cut was identified on the face of the handover. A build that merges them, pre-selects one from the other, or greys out the second has failed the Section 5.4 rules."}, "source_version_hash": "915ece3f71c4aa35261d72be5ef75cb53c1b2c741bbe91b0d0db49a6e5b81376"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D3-S2-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D3-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D3-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D3-S2-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D3-S3-001', 'source'::public.t3a_content_family, 'The migration window', 'D3', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D3-S3-001", "title": "The migration window", "stage": 3, "stage_code": "S3", "demonstration": true, "serving_eligible": false, "scenario_class": "work_sample", "d3_situation_class": "SC-D3-6", "interaction_pattern_family_id": "IPF-D3-06 (derived)", "administration_form_id": "AF-S3-ASYNC-SUBMISSION", "name_clearance_claim": "CLEARED", "compatibility_class": "DEMO-ONLY", "source_sheet": {"dimensions_in_play": "D3, sampled through the workplace demand of planning delivery inside a fixed window against an instruction that specifies almost nothing", "relevant_conduct": "the order of record sets stated; what is reduced or deferred if the window will not hold; which requirement is stated as held; which verifications are named; which means are used; what is done about the single-use rollback; whether the plan states what would be released incomplete", "irrelevant_conduct": "whether the plan would work; the technical migration approach; whether the instruction should have been clearer", "stated_standard": "\"the system is available to users at 06:00 on Monday and no record set is released without validation.\" Exact brief text", "permitted_administration_variance": "Extended time and assistive software permitted and recorded", "unsupported_inferences": "That any ordering is correct; that asking for clarification was required; anything about planning ability as a trait", "cross_context_map": "Not established; `min_seconds` / `max_seconds` — not_applicable, asynchronous Stage", "compatibility_class": "DEMO-ONLY", "work_items": "(a) `WI-01` record set one; (b) `WI-02` record set two; (c) `WI-03` record set three; (d) `WI-04` record set four", "deliverable_components": "(a) `DC-01` record set one migrated and released; (b) `DC-02` record set two migrated and released; (c) `DC-03` record set three migrated and released; (d) `DC-04` record set four migrated and released", "stated_requirements": "(a) `SR-01` the system is available to users at 06:00 on Monday; (b) `SR-02` no record set is released without validation; (c) `SR-03` downtime stays inside the window", "available_checks": "(a) `CK-01` the validation routine, about two hours per record set; evidenced in the submitted work, q_d3_04b_eligible true; (b) `CK-02` a release readiness confirmation before each set goes live; evidenced in the submitted work, q_d3_04b_eligible true", "available_means": "(a) `MN-01` run two record sets in parallel across the two people; evidenced in the submitted work, q_d3_05b_eligible true; (b) `MN-02` hold a record set back to a later window; evidenced in the submitted work, q_d3_05b_eligible true; (c) `MN-03` use the rollback procedure; evidenced in the submitted work, q_d3_05b_eligible true", "time_available": "\"about forty-eight hours in the window.\" Exact brief text", "work_required": "four record sets plus about two hours of validation each, with two people", "blocking_dependency": "the rollback procedure takes about six hours and can be run once", "dependency_holder_role": "not_applicable. The constraint is the procedure, not a person", "moved_standard_point": "explicit none. CE-D3-08 IS NOT IN LAUNCH DESIGN AT STAGE 3", "handover_point": "06:00 Monday, at release", "delivery_state_record": "not_applicable. CE-D3-09 IS NOT IN LAUNCH DESIGN AT STAGE 3", "delivery_test_point": "not_applicable. The asynchronous form creates no point at which the recorded state is put to the participant and a response observed", "mentor_action_sequence": "not_applicable. Stage 3 runs no beats", "d3_situation_class": "SC-D3-6"}, "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "The brief asks for the order directly"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "On Q-D3-01 A1 or A2. THE ORDER IS PERSISTED AS A SEQUENCE"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The brief asks what happens if the window will not hold all four"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "On Q-D3-02 A1, A2 or A3"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements that cannot all hold if the window is short"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "On Q-D3-03 A1"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The brief asks for the verification checklist"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "On Q-D3-04 A1 or A2"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means evidenced in the submission"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "On Q-D3-05 A1 or A2"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The single-use rollback is the constraint the participant does not get to retry"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The single-use rollback is the constraint the participant does not get to retry"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The brief asks what would be released incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "On Q-D3-07 A1 or A2"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "CE-D3-08 not in launch design at Stage 3. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "CE-D3-09 not in launch design at Stage 3. NO ANSWER ROW, NO MISSING-STATE CODE"}], "script": null, "reveals": [], "text_blocks": {"The brief as the participant meets it": "You coordinate a records migration for the client organization. The migration window is a single weekend and cannot be moved; the system is unavailable to users for its duration.\nThe instruction you received reads in full: \"Plan the weekend migration. Get the records across. Keep the downtime to the window.\"\nWhat you have: about forty-eight hours in the window; four record sets of roughly equal size; two people including yourself; a validation routine that takes about two hours per record set; a rollback procedure that takes about six hours and can be run once.\nThe service agreement states that the system is available to users at 06:00 on Monday and that no record set is released without validation.\nProduce: a migration plan stating the order you will take the record sets and why; a statement of what you will do if the window will not hold all four; and a checklist of what you will verify before each release, with what you would do if a validation fails."}, "narrative": {"The brief as the participant meets it": "> You coordinate a records migration for the client organization. The migration window is a single weekend and cannot be moved; the system is unavailable to users for its duration.\n>\n> The instruction you received reads in full: \"Plan the weekend migration. Get the records across. Keep the downtime to the window.\"\n>\n> What you have: about forty-eight hours in the window; four record sets of roughly equal size; two people including yourself; a validation routine that takes about two hours per record set; a rollback procedure that takes about six hours and can be run once.\n>\n> The service agreement states that the system is available to users at 06:00 on Monday and that no record set is released without validation.\n>\n> Produce: a migration plan stating the order you will take the record sets and why; a statement of what you will do if the window will not hold all four; and a checklist of what you will verify before each release, with what you would do if a validation fails.", "Submission": "Asynchronous. `min_seconds`, `max_seconds` and `mentor_script` are NULL and null is not an error. Eleven required provenance fields, with `prior_version_ref` a twelfth required only on a resubmission. Three declarations with controlled verbatim wording: authorship, tooling, third-party material. AI_USE_DECLARATION_REQUIRED is in force; a missing tooling declaration refuses and logs.", "What this fixture proves": "Two questions produce no row of any kind, and the report is silent about both. A build that writes a null, a `not_applicable` or a \"not observed\" sentence for either has failed."}, "source_version_hash": "6ed276d8ab07fdb5b8bdc06571264a4f83a52e6102604da9fd152da1ac192c50"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D3-S3-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
