insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D3-S4-001', 'source'::public.t3a_content_family, 'The date that moved', 'D3', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D3-S4-001", "title": "The date that moved", "stage": 4, "stage_code": "S4", "demonstration": true, "serving_eligible": false, "scenario_class": "team_simulation", "d3_situation_class": "SC-D3-3", "interaction_pattern_family_id": "IPF-D3-03 (derived)", "administration_form_id": "AF-S4-GROUP-ROUND", "name_clearance_claim": "CLEARED", "compatibility_class": "DEMO-ONLY", "source_sheet": {"dimensions_in_play": "D3, sampled through the workplace demand of replanning delivery when the date moves after work has begun", "relevant_conduct": "what was stated about the order of the three pieces; what was reduced, deferred or dropped; which acceptance criterion was stated as held; what verification was named; which means were used; what was done with the work already performed; the answer at B6", "irrelevant_conduct": "the conduct of CP-1, CP-2 or CP-3, which is scripted and never recorded; whether the new date is achievable; P-OBS''s manner", "stated_standard": "\"the interface test is signed off before go-live and the user acceptance pack is delivered at go-live.\" Exact pre-brief text", "permitted_administration_variance": "Pronunciation only. Accommodations affecting turn order or response window are recorded and set `timing_not_comparable`", "unsupported_inferences": "That P-OBS should have resisted the date; that dropping a piece was a failure; anything about adaptability as a trait", "cross_context_map": "Not established", "min_seconds": "900 / `max_seconds` — 1500", "compatibility_class": "DEMO-ONLY", "work_items": "(a) `WI-01` the configuration load — about one week; (b) `WI-02` the interface test — about one week; (c) `WI-03` the user acceptance pack — about one week", "deliverable_components": "(a) `DC-01` configuration load; (b) `DC-02` interface test; (c) `DC-03` user acceptance pack", "stated_requirements": "(a) `SR-01` the interface test is signed off before go-live; (b) `SR-02` the user acceptance pack is delivered at go-live", "available_checks": "(a) `CK-01` interface test sign-off; performable_in_session true as a stated commitment within the round; observable_act true, q_d3_04b_eligible true; (b) `CK-02` configuration load verification against the source records; performable_in_session true, observable_act true, q_d3_04b_eligible true", "available_means": "(a) `MN-01` run the configuration load and the interface test in parallel; performable_in_session true, observable_act true, q_d3_05b_eligible true; (b) `MN-02` ask the training strand to take part of the user acceptance pack; performable_in_session true, observable_act true, q_d3_05b_eligible true; (c) `MN-03` deliver the user acceptance pack after go-live; performable_in_session true, observable_act true, q_d3_05b_eligible true", "time_available": "one week. Exact pre-brief text", "work_required": "three pieces of about one week each", "blocking_dependency": "explicit none. NO PIECE OF THIS WORK SITS OUTSIDE P-OBS''S CONTROL, so Q-D3-06a and Q-D3-06b are NOT SERVED", "dependency_holder_role": "not_applicable", "moved_standard_point": "B1, when the facilitator states the date has moved forward by two weeks. THE MOVE IS THE SITUATION", "handover_point": "go-live, outside the observation. Q-D3-07 records what was stated about what would be handed over incomplete", "delivery_state_record": "at B6: the configuration load is part complete; the interface test is not started; the user acceptance pack is not started", "delivery_test_point": "B6", "mentor_action_sequence": "B1 SAY, is_decision_point false; B2 ROUND, is_decision_point TRUE; B3 ASK, serves the enquiry question; B4 ASK, serves Q-D3-02 and Q-D3-08; B5 ASK, serves Q-D3-04 and Q-D3-05; B6 ASK, serves Q-D3-09; B7 SAY, is_decision_point false", "d3_situation_class": "SC-D3-3"}, "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three pieces, one week; B2 and B3 create the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "On Q-D3-01 A1 or A2"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what happens to the pieces"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "On Q-D3-02 A1, A2 or A3"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two acceptance criteria that cannot both hold in one week"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "On Q-D3-03 A1"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what gets verified"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "On Q-D3-04 A1 or A2"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, all performable in the round"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "On Q-D3-05 A1 or A2"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "`blocking_dependency` is an explicit none. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "`blocking_dependency` is an explicit none. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 creates the opportunity to state what would go incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "On Q-D3-07 A1 or A2"}, {"question": "Q-D3-08", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT OF THIS FIXTURE. The move is at B1 and all of A1 to A4 are reachable"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "`delivery_test_point` at B6"}], "script": [{"beat": "B1", "type": "SAY", "verbatim_text": "\"The client organization has moved go-live forward by two weeks. This is to work out what that does to each strand, not to reopen the date. I will go round in this order — data, training, schedule, then build. Two minutes each.\"", "capture": null}, {"beat": "B2", "type": "ROUND", "verbatim_text": "CP-1, CP-2, CP-3 in that order. The facilitator does not address P-OBS", "capture": null}, {"beat": "B3", "type": "ASK 1", "verbatim_text": "\"Build strand. Where does the plan stand now?\"", "capture": null}, {"beat": "B4", "type": "ASK 2", "verbatim_text": "\"Three weeks of work in one. What happens to the pieces you had planned?\"", "capture": null}, {"beat": "B5", "type": "ASK 3", "verbatim_text": "\"What gets verified before go-live, and how?\"", "capture": null}, {"beat": "B6", "type": "ASK 4", "verbatim_text": "\"Just so the position is right — as of now, which of the three pieces is complete and which is not?\"", "capture": null}, {"beat": "B7", "type": "SAY", "verbatim_text": "\"That is the review. Thank you all.\"", "capture": null}], "reveals": [], "text_blocks": {"P-OBS pre-brief": "You run the build strand of a five-week implementation for the client organization. You are at the end of week three and the strand is on plan.\nYour plan has three remaining pieces: the configuration load, the interface test, and the user acceptance pack. Each takes about a week. The plan assumed five weeks.\nThis morning the client organization moved the go-live forward by two weeks. Three weeks of work now has to land in one.\nThe written acceptance criteria state that the interface test is signed off before go-live and that the user acceptance pack is delivered at go-live."}, "narrative": {"Model": "ONE OBSERVED PARTICIPANT (P-OBS), THREE CO-PARTICIPANTS (CP-1, CP-2, CP-3) who are role players and are NOT observed, one facilitator. ONE OBSERVATION RECORD IS WRITTEN, for P-OBS only. A Stage 4 group participation record is required for all four before entry. No recording.", "P-OBS pre-brief": "> You run the build strand of a five-week implementation for the client organization. You are at the end of week three and the strand is on plan.\n>\n> Your plan has three remaining pieces: the configuration load, the interface test, and the user acceptance pack. Each takes about a week. The plan assumed five weeks.\n>\n> This morning the client organization moved the go-live forward by two weeks. Three weeks of work now has to land in one.\n>\n> The written acceptance criteria state that the interface test is signed off before go-live and that the user acceptance pack is delivered at go-live.", "CP positions": "CP-1: you run the data strand; state that your strand is unaffected by the date change. CP-2: you run the training strand; state that you need the user acceptance pack a week before go-live. CP-3: you coordinate the schedule; state that the new date is fixed by the client organization.", "Facilitator card": "You are facilitating AND observing P-OBS only. At B1 you state the speaking order aloud: data, training, schedule, then build. During the B2 round you MUST NOT look at, gesture towards or address P-OBS. You read the scripted text verbatim and do not react expressively to anything anyone says.", "The four questions": "1. B3 — \"Build strand. Where does the plan stand now?\"\n2. B4 — \"Three weeks of work in one. What happens to the pieces you had planned?\"\n3. B5 — \"What gets verified before go-live, and how?\"\n4. B6 — \"Just so the position is right — as of now, which of the three pieces is complete and which is not?\"", "What this fixture proves": "Q-D3-08 is served here, with all four answers reachable, and NOT SERVED in the other three fixtures, because only this source moves the standard. Q-D3-06a and Q-D3-06b are NOT SERVED here and DIRECT in the other three. A build that hard-codes either behavior passes some fixtures and fails others. And CP-2''s statement that the training strand needs the pack a week early is A CHARACTER STATEMENT — it creates no requirement, and `stated_requirements` holds two items, not three."}, "source_version_hash": "a24be9865d7f5a1674b10a6ee00c5c8915b740fa8f03f800cea13e75262bcf5b"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D3-S4-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
